def compute(vars):
    basic = vars["v1"]
    diluted = vars["v2"]
    difference = basic - diluted
    return {
        "value": difference,
        "trace": {
            "basic_net_income_per_share": basic,
            "diluted_net_income_per_share": diluted,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "currency/share"
            }
        }
    }
